const { spawn } = require('child_process');
const path = require('path');
const fs = require('fs').promises;
const database = require('./database');
const { v4: uuidv4 } = require('uuid');

class SimulationService {
  constructor() {
    // Change from single simulation to multiple
    this.simulations = new Map(); // simulationId -> SimulationInstance
    // Point to the root-level executable if available
    this.cppExecutablePath = path.join(__dirname, '../../serina_evolution_engine.exe');
    // Store config near the API folder
    this.configPath = path.join(__dirname, '../../simulation_config.json');
    this.outputBuffer = [];
    this.maxBufferSize = 1000;
    this.dataCallback = null;
    // Python streaming integration
    this.pythonScriptPath = path.join(__dirname, '../../python/stream_sim.py');
    this.pythonExecutable = null; // 'py -3' on Windows or 'python'
    this.mode = 'auto'; // 'cpp' | 'python' | 'mock' | 'auto'
  }

  async initialize() {
    console.log('🔬 Initializing Simulation Service...');
    
    // Vérifier que l'exécutable C++ existe
    await this.validateCppExecutable();
    // Vérifier le script Python
    await this.validatePythonScript();
    
    // Créer le fichier de configuration par défaut si nécessaire
    await this.ensureConfigFile();
    
    console.log('✅ Simulation Service initialized');
  }

  async validateCppExecutable() {
    try {
      await fs.access(this.cppExecutablePath);
      console.log('✅ C++ executable found:', this.cppExecutablePath);
    } catch (error) {
      console.warn('⚠️ C++ executable not found, creating mock implementation');
      this.cppExecutablePath = null; // Use mock mode
    }
  }

  async validatePythonScript() {
    try {
      await fs.access(this.pythonScriptPath);
      // Try to select a python executable
      // Prefer Windows launcher
      this.pythonExecutable = process.platform === 'win32' ? 'py' : 'python3';
      console.log('✅ Python stream script found:', this.pythonScriptPath);
    } catch (error) {
      console.warn('⚠️ Python stream script not found or Python not configured');
      this.pythonExecutable = null;
    }
  }

  async ensureConfigFile() {
    try {
      await fs.access(this.configPath);
      console.log('✅ Config file found:', this.configPath);
    } catch (error) {
      // Ensure directory exists
      try {
        await fs.mkdir(path.dirname(this.configPath), { recursive: true });
      } catch (_) {}

      // Créer un fichier de configuration par défaut
      const defaultConfig = {
        simulation: {
          population_size: 150,
          environment_size: { width: 1920, height: 1080 },
          time_step: 0.016667, // 60 FPS
          max_generations: 1000,
          mutation_rate: 0.1,
          crossover_rate: 0.7
        },
        environment: {
          food_sources: 50,
          temperature: 20.0,
          humidity: 0.6,
          oxygen_level: 0.21,
          radiation_level: 0.0
        },
        genetics: {
          trait_count: 12,
          gene_pool_diversity: 0.8,
          inheritance_variance: 0.15,
          phenotype_expression_strength: 0.9
        },
        performance: {
          enable_multithreading: true,
          thread_count: 4,
          enable_simd: true,
          memory_pool_size: "64MB"
        }
      };

      try {
        await fs.writeFile(this.configPath, JSON.stringify(defaultConfig, null, 2));
        console.log('✅ Created default config file:', this.configPath);
      } catch (e) {
        console.warn('⚠️ Could not write simulation config file, proceeding without one:', e.message);
        this.configPath = null;
      }
    }
  }

  // Legacy method for backward compatibility
  async startSimulation(config = null) {
    return this.createSimulation(config);
  }

  // New method to create a specific simulation
  async createSimulation(config = null, simulationId = null) {
    const id = simulationId || uuidv4();
    
    if (this.simulations.has(id)) {
      throw new Error(`Simulation ${id} is already running`);
    }

    try {
      console.log(`🚀 Starting simulation ${id}...`);

      const desiredMode = (config && config.mode) ? config.mode : this.mode;
      let runMode = desiredMode;
      if (desiredMode === 'auto') {
        runMode = this.cppExecutablePath ? 'cpp' : (this.pythonExecutable ? 'python' : 'mock');
      }

      const simulationInstance = {
        id,
        mode: runMode,
        config: config || {},
        process: null,
        isRunning: false,
        startTime: new Date(),
        outputBuffer: [],
        dataCallback: null
      };

      this.simulations.set(id, simulationInstance);

      if (runMode === 'cpp' && this.cppExecutablePath) {
        await this.startCppSimulation(simulationInstance);
      } else if (runMode === 'python' && this.pythonExecutable) {
        await this.startPythonSimulation(simulationInstance);
      } else {
        await this.startSerinaSimulation(simulationInstance);
        simulationInstance.mode = 'mock';
      }

      simulationInstance.isRunning = true;
      console.log(`✅ Simulation ${id} started successfully`);

      return {
        success: true,
        message: 'Simulation started',
        simulationId: id,
        mode: runMode
      };

    } catch (error) {
      console.error(`❌ Failed to start simulation ${id}:`, error);
      this.simulations.delete(id);
      throw error;
    }
  }

  // Get all running simulations
  getRunningSimulations() {
    const running = [];
    for (const [id, simulation] of this.simulations.entries()) {
      if (simulation.isRunning) {
        running.push({
          id,
          mode: simulation.mode,
          startTime: simulation.startTime,
          config: simulation.config
        });
      }
    }
    return running;
  }

  // Get specific simulation status
  getSimulationStatus(simulationId) {
    const simulation = this.simulations.get(simulationId);
    if (!simulation) {
      return null;
    }
    return {
      id: simulationId,
      mode: simulation.mode,
      isRunning: simulation.isRunning,
      startTime: simulation.startTime,
      config: simulation.config
    };
  }

  // Legacy getter for backward compatibility
  get isRunning() {
    return this.simulations.size > 0 && 
           Array.from(this.simulations.values()).some(sim => sim.isRunning);
  }

  async startPythonSimulation(simulationInstance) {
    return new Promise((resolve, reject) => {
      const args = [this.pythonScriptPath];
      // On Windows, prefer 'py -3' if available
      let command = this.pythonExecutable || 'python';
      let finalArgs = args;
      if (process.platform === 'win32' && command === 'py') {
        finalArgs = ['-3', ...args];
      }

      simulationInstance.process = spawn(command, finalArgs, {
        cwd: path.dirname(this.pythonScriptPath),
        stdio: ['pipe', 'pipe', 'pipe']
      });

      let started = false;

      simulationInstance.process.stdout.on('data', (data) => {
        const text = data.toString();
        // The python script will emit JSON lines; handle line by line
        text.split(/\r?\n/).forEach(line => {
          const trimmed = line.trim();
          if (!trimmed) return;
          this.handleSimulationOutput(trimmed, simulationInstance);
          started = true;
        });
      });

      simulationInstance.process.stderr.on('data', (data) => {
        console.error(`Python Simulation ${simulationInstance.id} stderr:`, data.toString());
      });

      simulationInstance.process.on('error', (error) => {
        console.error(`Python Simulation ${simulationInstance.id} process error:`, error);
        simulationInstance.isRunning = false;
        reject(error);
      });

      simulationInstance.process.on('exit', (code, signal) => {
        console.log(`Python Simulation ${simulationInstance.id} process exited with code ${code}, signal ${signal}`);
        simulationInstance.isRunning = false;
        this.simulations.delete(simulationInstance.id);
      });

      setTimeout(() => {
        if (started) resolve(); else resolve(); // Consider it started after initial buffer
      }, 1000);
    });
  }

  async startCppSimulation(simulationInstance) {
    return new Promise((resolve, reject) => {
      // Configure arguments based on SimulationAPI.hpp interface
      const args = [];
      if (this.configPath) {
        args.push('--config', this.configPath);
      }
      args.push('--json-output');  // Request JSON frames
      args.push('--realtime');
      
      simulationInstance.process = spawn(this.cppExecutablePath, args, {
        cwd: path.dirname(this.cppExecutablePath),
        stdio: ['pipe', 'pipe', 'pipe']
      });

      // Send initialization commands via stdin if needed
      if (this.simulationProcess.stdin) {
        const initCommand = JSON.stringify({
          command: 'initialize',
          worldWidth: 1920,
          worldHeight: 1080
        }) + '\n';
        this.simulationProcess.stdin.write(initCommand);
      }

      this.simulationProcess.stdout.on('data', (data) => {
        this.handleSimulationOutput(data.toString());
      });

      this.simulationProcess.stderr.on('data', (data) => {
        console.error('C++ Simulation stderr:', data.toString());
      });

      this.simulationProcess.on('error', (error) => {
        console.error('C++ Simulation process error:', error);
        this.isRunning = false;
        reject(error);
      });

      this.simulationProcess.on('exit', (code, signal) => {
        console.log(`C++ Simulation process exited with code ${code}, signal ${signal}`);
        this.isRunning = false;
      });

      // Wait for initial output to confirm startup
      setTimeout(() => {
        if (this.simulationProcess && !this.simulationProcess.killed) {
          resolve();
        } else {
          reject(new Error('C++ Simulation process failed to start'));
        }
      }, 2000);
    });
  }

  async startRealSimulation(simulationInstance) {
    console.log(`� Starting Serina evolution simulation ${simulationInstance.id}`);
    
    // Initialiser une vraie simulation de Serina avec les données authentiques
    simulationInstance.serinaData = this.initializeSerinaWorld();
    
    // Simulation évolutive en temps réel
    simulationInstance.evolutionInterval = setInterval(() => {
      this.evolveSerina(simulationInstance);
    }, 2000); // Évolution toutes les 2 secondes

    return Promise.resolve();
  }

  initializeSerinaWorld() {
    // Monde de Serina basé sur les 5 espèces fondatrices
    return {
      generation: 1,
      worldSize: { width: 2000, height: 1500 },
      foundingSpecies: ['Canaries', 'Grillons', 'Fourmis de feu', 'Guppys/Mollys', 'Escargots'],
      currentTime: Date.now(),
      ecosystemAge: 0, // en années Serina
      species: [
        this.createSerinaSpecies('Canaris de Serina', 'Canaria serina', 'Aerial insectivore', 45),
        this.createSerinaSpecies('Grillons des prairies', 'Gryllus seriensis', 'Ground herbivore', 230),
        this.createSerinaSpecies('Fourmis colonisatrices', 'Solenopsis adaptans', 'Social omnivore', 1800),
        this.createSerinaSpecies('Poissons des rivières', 'Poecilia aquatica', 'Aquatic filter feeder', 78),
        this.createSerinaSpecies('Escargots forestiers', 'Achatina gigantis', 'Forest decomposer', 34)
      ],
      environment: {
        continent: 'Continents principaux de Serina',
        biomes: {
          'Forêts tempérées': 0.35,
          'Prairies': 0.28,
          'Zones humides': 0.15,
          'Montagnes': 0.12,
          'Côtes': 0.10
        },
        climate: {
          temperature: 18.5, // °C moyen global
          humidity: 0.72,
          precipitation: 0.68,
          seasonality: 0.45
        }
      },
      totalPopulation: 2187,
      totalMutations: 0,
      totalReproductions: 0,
      extinctionEvents: 0
    };
  }

  createSerinaSpecies(name, scientificName, niche, population) {
    return {
      id: `serina_${name.toLowerCase().replace(/\s+/g, '_')}`,
      name: name,
      scientificName: scientificName,
      ecologicalNiche: niche,
      populationCount: population,
      generationSpan: Math.floor(Math.random() * 20) + 5,
      extinctionRisk: Math.random() * 0.3,
      averageTrait: {
        SIZE: 0.3 + Math.random() * 0.4,
        SPEED: 0.3 + Math.random() * 0.4, 
        STRENGTH: 0.3 + Math.random() * 0.4,
        INTELLIGENCE: 0.2 + Math.random() * 0.6,
        LONGEVITY: 0.3 + Math.random() * 0.4,
        RESISTANCE: 0.4 + Math.random() * 0.3,
        METABOLISM: 0.4 + Math.random() * 0.3,
        SOCIABILITY: Math.random() * 0.8,
        ADAPTABILITY: 0.5 + Math.random() * 0.3,
        VISION_RANGE: 0.3 + Math.random() * 0.4,
        CAMOUFLAGE: Math.random() * 0.6,
        REPRODUCTION_RATE: 0.4 + Math.random() * 0.4
      },
      individuals: []
    };
  }

  evolveSerina(simulationInstance) {
    const serinaData = simulationInstance.serinaData;
    
    // Avancer le temps de Serina
    serinaData.ecosystemAge += 0.1; // 0.1 année par cycle
    serinaData.generation = Math.floor(serinaData.ecosystemAge * 10);
    
    // Évolution des espèces
    let totalPopulation = 0;
    let totalMutations = 0;
    let totalReproductions = 0;
    
    serinaData.species.forEach(species => {
      // Reproduction naturelle
      const reproductionRate = species.averageTrait.REPRODUCTION_RATE;
      const environmentalFactor = this.calculateEnvironmentalPressure(serinaData.environment);
      
      const growthRate = (reproductionRate * environmentalFactor) - species.extinctionRisk;
      const populationChange = Math.floor(species.populationCount * growthRate * 0.05);
      
      species.populationCount = Math.max(1, species.populationCount + populationChange);
      totalPopulation += species.populationCount;
      
      // Mutations adaptatives
      if (Math.random() < 0.15) {
        this.mutateSerinaSpecies(species);
        totalMutations++;
      }
      
      // Reproduction events
      if (Math.random() < reproductionRate) {
        totalReproductions += Math.floor(Math.random() * 5) + 1;
      }
      
      // Mise à jour du risque d'extinction
      species.extinctionRisk = Math.max(0, Math.min(1, 
        species.extinctionRisk + (Math.random() - 0.5) * 0.05
      ));
    });
    
    serinaData.totalPopulation = totalPopulation;
    serinaData.totalMutations += totalMutations;
    serinaData.totalReproductions += totalReproductions;
    
    // Mise à jour environnementale
    this.updateSerinaEnvironment(serinaData);
    
    // Formater les données pour l'interface
    const simulationData = this.formatSerinaDataForUI(serinaData);
    this.handleSimulationOutput(JSON.stringify(simulationData), simulationInstance);
  }

  mutateSerinaSpecies(species) {
    const traits = Object.keys(species.averageTrait);
    const randomTrait = traits[Math.floor(Math.random() * traits.length)];
    const mutationStrength = (Math.random() - 0.5) * 0.1; // ±5% max
    
    species.averageTrait[randomTrait] = Math.max(0, Math.min(1, 
      species.averageTrait[randomTrait] + mutationStrength
    ));
  }

  calculateEnvironmentalPressure(environment) {
    // Facteur basé sur les conditions environnementales de Serina
    const tempOptimal = Math.abs(environment.climate.temperature - 20) / 20;
    const humidityFactor = environment.climate.humidity;
    const precipitationFactor = environment.climate.precipitation;
    
    return (humidityFactor + precipitationFactor + (1 - tempOptimal)) / 3;
  }

  updateSerinaEnvironment(serinaData) {
    // Changements climatiques graduels de Serina
    const env = serinaData.environment.climate;
    
    env.temperature += (Math.random() - 0.5) * 0.2;
    env.humidity += (Math.random() - 0.5) * 0.02;
    env.precipitation += (Math.random() - 0.5) * 0.03;
    
    // Maintenir dans des limites réalistes
    env.temperature = Math.max(10, Math.min(30, env.temperature));
    env.humidity = Math.max(0.4, Math.min(0.9, env.humidity));
    env.precipitation = Math.max(0.2, Math.min(0.9, env.precipitation));
  }

  formatSerinaDataForUI(serinaData) {
    return {
      timestamp: Date.now(),
      populationCount: serinaData.totalPopulation,
      generation: serinaData.generation,
      worldState: {
        generation: serinaData.generation,
        totalPopulation: serinaData.totalPopulation,
        species: serinaData.species,
        environment: {
          temperature: serinaData.environment.climate.temperature,
          humidity: serinaData.environment.climate.humidity,
          precipitation: serinaData.environment.climate.precipitation,
          resourceAbundance: this.calculateResourceAbundance(serinaData),
          predationPressure: this.calculatePredationPressure(serinaData),
          diseaseLoad: Math.random() * 0.3,
          seasonalModifier: 0.5 + Math.sin(serinaData.ecosystemAge * 4) * 0.3,
          dayNightCycle: (Date.now() / 86400000) % 1
        },
        worldSize: serinaData.worldSize,
        terrainMap: this.generateSerinaTerrainMap(serinaData),
        climateMap: this.generateSerinaClimateMap(serinaData),
        resourceMap: this.generateSerinaResourceMap(serinaData),
        time: {
          elapsed: serinaData.ecosystemAge * 365 * 24 * 3600, // en secondes
          generation: serinaData.generation,
          dayNightCycle: (Date.now() / 86400000) % 1,
          season: this.getCurrentSerinaSeason(serinaData.ecosystemAge)
        }
      },
      species: serinaData.species,
      evolutionStats: {
        totalMutations: serinaData.totalMutations,
        totalReproductions: serinaData.totalReproductions,
        averageFitness: this.calculateAverageFitness(serinaData.species),
        geneticDiversity: this.calculateGeneticDiversity(serinaData.species),
        speciesCount: serinaData.species.length,
        extinctionRate: serinaData.extinctionEvents / (serinaData.generation || 1)
      },
      performance: {
        generationsPerSecond: 0.5, // Évolution lente et réaliste
        memoryUsage: 32.5 + Math.random() * 10,
        cpuUsage: 15.2 + Math.random() * 15,
        frameRate: 30.0
      },
      events: this.generateSerinaEvents(serinaData)
    };
  }

  calculateResourceAbundance(serinaData) {
    const biomes = serinaData.environment.biomes;
    return (biomes['Forêts tempérées'] * 0.8 + biomes['Prairies'] * 0.6 + 
            biomes['Zones humides'] * 0.9 + biomes['Montagnes'] * 0.3);
  }

  calculatePredationPressure(serinaData) {
    // Prédation basée sur la population et la diversité
    const populationDensity = serinaData.totalPopulation / 10000;
    const speciesDiversity = serinaData.species.length / 10;
    return Math.min(0.8, populationDensity * 0.3 + speciesDiversity * 0.2);
  }

  generateSerinaTerrainMap(serinaData) {
    // Carte de terrain simplifiée pour Serina
    const map = [];
    for (let i = 0; i < 100; i++) {
      map.push({
        x: Math.random() * serinaData.worldSize.width,
        y: Math.random() * serinaData.worldSize.height,
        type: ['forest', 'grassland', 'wetland', 'mountain', 'coast'][Math.floor(Math.random() * 5)],
        elevation: Math.random() * 1000
      });
    }
    return map;
  }

  generateSerinaClimateMap(serinaData) {
    const map = [];
    for (let i = 0; i < 50; i++) {
      map.push({
        x: Math.random() * serinaData.worldSize.width,
        y: Math.random() * serinaData.worldSize.height,
        temperature: serinaData.environment.climate.temperature + (Math.random() - 0.5) * 10,
        humidity: serinaData.environment.climate.humidity + (Math.random() - 0.5) * 0.3,
        precipitation: serinaData.environment.climate.precipitation + (Math.random() - 0.5) * 0.4
      });
    }
    return map;
  }

  generateSerinaResourceMap(serinaData) {
    const map = [];
    for (let i = 0; i < 75; i++) {
      map.push({
        x: Math.random() * serinaData.worldSize.width,
        y: Math.random() * serinaData.worldSize.height,
        type: ['seeds', 'insects', 'water', 'minerals', 'shelter'][Math.floor(Math.random() * 5)],
        abundance: Math.random()
      });
    }
    return map;
  }

  getCurrentSerinaSeason(ecosystemAge) {
    const seasonIndex = Math.floor((ecosystemAge * 4) % 4);
    return ['Printemps', 'Été', 'Automne', 'Hiver'][seasonIndex];
  }

  calculateAverageFitness(species) {
    if (species.length === 0) return 0;
    const totalFitness = species.reduce((sum, sp) => {
      const traitValues = Object.values(sp.averageTrait);
      const avgTrait = traitValues.reduce((a, b) => a + b, 0) / traitValues.length;
      return sum + avgTrait * (1 - sp.extinctionRisk);
    }, 0);
    return totalFitness / species.length;
  }

  calculateGeneticDiversity(species) {
    if (species.length === 0) return 0;
    
    let diversitySum = 0;
    species.forEach(sp => {
      const traitValues = Object.values(sp.averageTrait);
      const variance = this.calculateVariance(traitValues);
      diversitySum += variance;
    });
    
    return Math.min(1, diversitySum / species.length);
  }

  calculateVariance(values) {
    const mean = values.reduce((a, b) => a + b, 0) / values.length;
    const variance = values.reduce((sum, val) => sum + Math.pow(val - mean, 2), 0) / values.length;
    return variance;
  }

  generateSerinaEvents(serinaData) {
    const events = [];
    
    // Événements évolutifs spécifiques à Serina
    if (Math.random() < 0.2) {
      events.push({
        type: 'adaptation',
        description: 'Une espèce développe une nouvelle adaptation aux conditions de Serina',
        species: serinaData.species[Math.floor(Math.random() * serinaData.species.length)].name,
        timestamp: Date.now()
      });
    }
    
    if (Math.random() < 0.1) {
      events.push({
        type: 'migration',
        description: 'Mouvement migratoire entre les biomes de Serina',
        impact: 'Population redistribuée',
        timestamp: Date.now()
      });
    }
    
    if (Math.random() < 0.05) {
      events.push({
        type: 'environmental_change',
        description: 'Changement climatique graduel de Serina',
        effect: `Température: ${serinaData.environment.climate.temperature.toFixed(1)}°C`,
        timestamp: Date.now()
      });
    }
    
    return events;
  }

  handleSimulationOutput(output, simulationInstance) {
    try {
      // Ajouter au buffer de la simulation spécifique
      simulationInstance.outputBuffer.push({
        timestamp: Date.now(),
        data: output.trim()
      });

      // Limiter la taille du buffer
      if (simulationInstance.outputBuffer.length > this.maxBufferSize) {
        simulationInstance.outputBuffer = simulationInstance.outputBuffer.slice(-this.maxBufferSize);
      }

      // Essayer de parser comme JSON (données de simulation)
      try {
        const data = JSON.parse(output);
        this.processSimulationData(data, simulationInstance);
      } catch (parseError) {
        // Si ce n'est pas du JSON, c'est probablement un message de log
        console.log(`Simulation ${simulationInstance.id} log:`, output);
      }

    } catch (error) {
      console.error(`Error handling simulation ${simulationInstance.id} output:`, error);
    }
  }

  // Stop specific simulation
  async stopSimulation(simulationId = null) {
    if (!simulationId) {
      // Legacy mode - stop the first running simulation
      const firstRunning = Array.from(this.simulations.values()).find(sim => sim.isRunning);
      if (firstRunning) {
        simulationId = firstRunning.id;
      } else {
        throw new Error('No running simulations to stop');
      }
    }

    const simulation = this.simulations.get(simulationId);
    if (!simulation) {
      throw new Error(`Simulation ${simulationId} not found`);
    }

    if (!simulation.isRunning) {
      throw new Error(`Simulation ${simulationId} is not running`);
    }

    try {
      console.log(`🛑 Stopping simulation ${simulationId}...`);

      if (simulation.process) {
        simulation.process.kill('SIGTERM');
        // Wait briefly for graceful shutdown
        await new Promise(resolve => setTimeout(resolve, 1000));
        
        if (!simulation.process.killed) {
          simulation.process.kill('SIGKILL');
        }
      }

      if (simulation.evolutionInterval) {
        clearInterval(simulation.evolutionInterval);
      }
      
      if (simulation.offlineInterval) {
        clearInterval(simulation.offlineInterval);
      }
      
      if (simulation.serinaProcess) {
        simulation.serinaProcess.kill();
      }

      simulation.isRunning = false;
      this.simulations.delete(simulationId);

      console.log(`✅ Simulation ${simulationId} stopped`);
      return {
        success: true,
        message: `Simulation ${simulationId} stopped`,
        simulationId
      };

    } catch (error) {
      console.error(`❌ Failed to stop simulation ${simulationId}:`, error);
      throw error;
    }
  }

  // Stop all simulations
  async stopAllSimulations() {
    const results = [];
    for (const simulationId of this.simulations.keys()) {
      try {
        const result = await this.stopSimulation(simulationId);
        results.push(result);
      } catch (error) {
        results.push({
          success: false,
          simulationId,
          error: error.message
        });
      }
    }
    return results;
  }

  async processSimulationData(data, simulationInstance) {
    try {
      // Sauvegarder les données dans la base de données
      if (data.generation !== undefined) {
        await database.updateSimulation(1, {
          current_generation: data.generation,
          population_count: data.population_count,
          species_count: data.species_count,
          last_update: new Date()
        });
      }

      // Record species traits history if species data is available
      if (data.species_details && Array.isArray(data.species_details) && data.generation !== undefined) {
        for (const species of data.species_details) {
          if (species.id && species.traits && species.population_count) {
            const traitsData = {
              populationCount: species.population_count,
              avgTraits: species.traits,
              fitnessAverage: species.fitness_average || 0,
              geneticDiversity: species.genetic_diversity || 0,
              mutationRate: species.mutation_rate || 0,
              extinctionRisk: species.extinction_risk || 0,
              environmentalPressures: data.environment || {}
            };
            
            try {
              await database.saveSpeciesTraitsHistory(
                species.id, 
                1, // simulation_id 
                data.generation, 
                traitsData
              );
            } catch (traitError) {
              console.warn(`Could not save traits history for species ${species.id}:`, traitError.message);
            }
          }
        }
      }

      // Traiter les événements
      if (data.events && Array.isArray(data.events)) {
        for (const event of data.events) {
          await this.processSimulationEvent(event, data);
        }
      }

      // Propager les données au callback (WebSocket, etc.)
      if (typeof this.dataCallback === 'function') {
        try { this.dataCallback(data); } catch (_) {}
      }

    } catch (error) {
      console.error('Error processing simulation data:', error);
    }
  }

  async processSimulationEvent(event, simulationData) {
    try {
      switch (event.type) {
        case 'reproduction':
          await this.handleReproductionEvent(event, simulationData);
          break;
        case 'mutation':
          await this.handleMutationEvent(event, simulationData);
          break;
        case 'death':
          await this.handleDeathEvent(event, simulationData);
          break;
        case 'environment_change':
          await this.handleEnvironmentChange(event, simulationData);
          break;
        default:
          console.log('Unknown event type:', event.type);
      }
    } catch (error) {
      console.error('Error processing simulation event:', error);
    }
  }

  async handleReproductionEvent(event, data) {
    // Enregistrer l'événement de reproduction
    await database.query(`
      INSERT INTO evolution_events (simulation_id, species_id, event_type, event_data, generation, recorded_at)
      VALUES (?, ?, ?, ?, ?, ?)
    `, [1, event.species_id || null, 'reproduction', JSON.stringify(event), data.generation || 0, new Date()]);
  }

  async handleMutationEvent(event, data) {
    // Enregistrer l'événement de mutation
    await database.query(`
      INSERT INTO evolution_events (simulation_id, species_id, event_type, event_data, generation, recorded_at)
      VALUES (?, ?, ?, ?, ?, ?)
    `, [1, event.species_id || null, 'mutation', JSON.stringify(event), data.generation || 0, new Date()]);
  }

  async handleDeathEvent(event, data) {
    // Marquer l'individu comme mort
    if (event.individual_id) {
      await database.updateIndividual(event.individual_id, {
        is_alive: false,
        death_time: new Date(),
        cause_of_death: event.reason || 'simulation_event'
      });
    }
  }

  async handleEnvironmentChange(event, data) {
    // Ajouter au change_history JSON dans la table environment
    const env = await database.getEnvironmentBySimulation(1);
    const history = (env && env.change_history) ? (typeof env.change_history === 'string' ? JSON.parse(env.change_history) : env.change_history) : [];
    history.push({
      type: event.type,
      at: new Date().toISOString(),
      details: data.environment || {}
    });
    await database.updateEnvironment(1, { change_history: history });
  }

  async stopSimulation() {
    if (!this.isRunning) {
      throw new Error('No simulation is currently running');
    }

    try {
      console.log('🛑 Stopping simulation...');

      if (this.simulationProcess) {
        this.simulationProcess.kill('SIGTERM');
        this.simulationProcess = null;
      }

      if (this.mockSimulationInterval) {
        clearInterval(this.mockSimulationInterval);
        this.mockSimulationInterval = null;
      }

      this.isRunning = false;
      console.log('✅ Simulation stopped successfully');

      return {
        success: true,
        message: 'Simulation stopped'
      };

    } catch (error) {
      console.error('❌ Failed to stop simulation:', error);
      throw error;
    }
  }

  async pauseSimulation() {
    if (!this.isRunning) {
      throw new Error('No simulation is currently running');
    }

    try {
      if (this.simulationProcess) {
        this.simulationProcess.kill('SIGUSR1'); // Signal pour pause
      }

      console.log('⏸️ Simulation paused');
      return { success: true, message: 'Simulation paused' };

    } catch (error) {
      console.error('❌ Failed to pause simulation:', error);
      throw error;
    }
  }

  async resumeSimulation() {
    if (!this.isRunning) {
      throw new Error('No simulation is currently running');
    }

    try {
      if (this.simulationProcess) {
        this.simulationProcess.kill('SIGUSR2'); // Signal pour reprendre
      }

      console.log('▶️ Simulation resumed');
      return { success: true, message: 'Simulation resumed' };

    } catch (error) {
      console.error('❌ Failed to resume simulation:', error);
      throw error;
    }
  }

  async updateConfig(newConfig) {
    try {
      // Lire la configuration actuelle
      const currentConfigData = await fs.readFile(this.configPath, 'utf8');
      const currentConfig = JSON.parse(currentConfigData);

      // Fusionner avec la nouvelle configuration
      const updatedConfig = { ...currentConfig, ...newConfig };

      // Écrire la nouvelle configuration
      await fs.writeFile(this.configPath, JSON.stringify(updatedConfig, null, 2));

      console.log('✅ Configuration updated');
      return updatedConfig;

    } catch (error) {
      console.error('❌ Failed to update config:', error);
      throw error;
    }
  }

  async getConfig() {
    try {
      const configData = await fs.readFile(this.configPath, 'utf8');
      return JSON.parse(configData);
    } catch (error) {
      console.error('❌ Failed to read config:', error);
      throw error;
    }
  }

  getSimulationStatus() {
    return {
      isRunning: this.isRunning,
      mode: this.cppExecutablePath ? 'cpp' : 'mock',
      processId: this.simulationProcess ? this.simulationProcess.pid : null,
      outputBufferSize: this.outputBuffer.length
    };
  }

  getRecentOutput(count = 10) {
    return this.outputBuffer.slice(-count);
  }

  // Définir un callback pour recevoir les données JSON de simulation
  setDataCallback(callback) {
    this.dataCallback = callback;
  }

  async cleanup() {
    console.log('🧹 Cleaning up Simulation Service...');
    
    if (this.isRunning) {
      await this.stopSimulation();
    }

    this.outputBuffer = [];
    console.log('✅ Simulation Service cleanup complete');
  }
}

module.exports = SimulationService;